INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120879','Restaurant Local Site','Teknologi, Produk & Pembangunan','Bertindak sebagai pakar berpengalaman dalam local business dengan pendekatan berasaskan brief dan QA profesional. PROJEK SEBENAR: Website restoran tempatan dengan menu, harga, lokasi, jam dan cara tempah. KONTEKS: lokasi [LOKASI], audiens [AUDIENS], keperluan utama [OBJEKTIF], jenama [JENAMA], bahasa output [BAHASA]. TUGAS: Bina halaman menu responsif, pautan peta, no fake booking, seo local dan semakan fakta. Sediakan hasil kerja siap guna dalam bahagian: brief terisi, spesifikasi utama, draf/artifak akhir terperinci, contoh penggunaan sebenar, senarai aset yang diperlukan, dan checklist QA. Sekiranya input harga, statistik, kesaksian, identiti atau bahan sumber belum diberikan, tandakan TIDAK DISAHKAN dan jangan reka maklumat. Jelaskan perkara yang memerlukan kelulusan manusia atau ujian sebelum penerbitan.',NULL,'NOT TESTED','base','0903d46eea23a28b1dc907bcc924cbec9204193f1816a7e9db8620f7dc08dcb0');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120880','Notion-Style Knowledge Hub','Teknologi, Produk & Pembangunan','Bertindak sebagai pakar berpengalaman dalam knowledge base dengan pendekatan berasaskan brief dan QA profesional. PROJEK SEBENAR: Pusat tutorial AI dengan search, facet, breadcrumb dan toc artikel. KONTEKS: lokasi [LOKASI], audiens [AUDIENS], keperluan utama [OBJEKTIF], jenama [JENAMA], bahasa output [BAHASA]. TUGAS: Hasilkan reka bentuk taksonomi, satu klik salin code, feedback article dan mobile navigation. Sediakan hasil kerja siap guna dalam bahagian: brief terisi, spesifikasi utama, draf/artifak akhir terperinci, contoh penggunaan sebenar, senarai aset yang diperlukan, dan checklist QA. Sekiranya input harga, statistik, kesaksian, identiti atau bahan sumber belum diberikan, tandakan TIDAK DISAHKAN dan jangan reka maklumat. Jelaskan perkara yang memerlukan kelulusan manusia atau ujian sebelum penerbitan.',NULL,'NOT TESTED','base','8ea4df408abe19af59c9130d12462cf96765d41341e73b72e9364bfe0e4830e2');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120881','Member Magic Link Flow','Teknologi, Produk & Pembangunan','Bertindak sebagai pakar berpengalaman dalam auth dengan pendekatan berasaskan brief dan QA profesional. PROJEK SEBENAR: Log masuk passwordless dengan kegemaran disegerakkan merentas peranti. KONTEKS: lokasi [LOKASI], audiens [AUDIENS], keperluan utama [OBJEKTIF], jenama [JENAMA], bahasa output [BAHASA]. TUGAS: Gunakan email otp supabase, rls, sesi, sign out, retry/rate limit dan privacy consent. Sediakan hasil kerja siap guna dalam bahagian: brief terisi, spesifikasi utama, draf/artifak akhir terperinci, contoh penggunaan sebenar, senarai aset yang diperlukan, dan checklist QA. Sekiranya input harga, statistik, kesaksian, identiti atau bahan sumber belum diberikan, tandakan TIDAK DISAHKAN dan jangan reka maklumat. Jelaskan perkara yang memerlukan kelulusan manusia atau ujian sebelum penerbitan.',NULL,'NOT TESTED','base','f3028ed5b94b951e170536382e66d71e3b0eb5e87a4819ad633700338997f710');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120882','Website Quality Audit','Teknologi, Produk & Pembangunan','Bertindak sebagai pakar berpengalaman dalam qa dengan pendekatan berasaskan brief dan QA profesional. PROJEK SEBENAR: Audit laman jualan digital pada telefon dan desktop sebelum penerbitan. KONTEKS: lokasi [LOKASI], audiens [AUDIENS], keperluan utama [OBJEKTIF], jenama [JENAMA], bahasa output [BAHASA]. TUGAS: Hasilkan matriks responsif 375/768/1440, audit pautan, keyboard, wcag, analytics consent, core web vitals dan laporan pass/fail. Sediakan hasil kerja siap guna dalam bahagian: brief terisi, spesifikasi utama, draf/artifak akhir terperinci, contoh penggunaan sebenar, senarai aset yang diperlukan, dan checklist QA. Sekiranya input harga, statistik, kesaksian, identiti atau bahan sumber belum diberikan, tandakan TIDAK DISAHKAN dan jangan reka maklumat. Jelaskan perkara yang memerlukan kelulusan manusia atau ujian sebelum penerbitan.',NULL,'NOT TESTED','base','d53b04ea8f38158c647474418378dc51f91d9f3c89e5b431682690e021be355e');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120883','Prompt nota jadi kuiz','Pendidikan & Pembelajaran','Jadi rakan kuiz saya. Guna hanya nota di bawah sebagai rujukan.
Tanya satu soalan pendek pada satu masa dalam BM Malaysia. Jangan beri jawapan sebelum saya menjawab.
Selepas saya jawab, semak jawapan saya dan petik ayat nota yang menyokong semakan.
Jika maklumat tiada, sebut “Tiada dalam nota”. Jangan tambah fakta luar.
Selepas tiga soalan, senaraikan perkara yang perlu saya ulang kaji.
NOTA: [Tampal nota anda]',NULL,'NOT TESTED','base','a7190841d076687ff8f7379019d493f3f2202534f59497674848f0be9ddf42a0');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('MA-120884','Build website full-stack','Teknologi, Produk & Pembangunan','''@Sites — BUILD AICHEATCODE × ARTSCIPES HUB, FULL-STACK WEBSITE

Bertindak sebagai Senior Full-stack Engineer, Product Designer, CMS Architect, Security Engineer, SEO Strategist dan QA Lead. Bina **website sebenar yang interaktif, dinamik, responsif, kreatif dan boleh digunakan**, bukan mockup kosong.

Gunakan fail yang saya bekalkan dalam pakej projek ini: `index.html`, `styles.css`, `data.js`, `app.js`, `SPESIFIKASI_PENUH_BM.md`, `README.md`, `qa_results.json`, serta inventori sumber saya (Book1, Linktree audit, katalog Notion, database prompts, social channels). Gunakan `SPESIFIKASI_PENUH_BM.md` sebagai kontrak fungsi dan keselamatan, tetapi jangan anggap semua pautan dan hak produk telah disahkan.

Jenama induk Artscipes Hub; subjenama AICheatcode. Buat pusat pengalaman AI AICheatcode (prompt percuma, prompt studio, AI tools, tutorial, komuniti) dan Artscipes Hub Digital Marketplace (ebook, planner, worksheet, coloring books, video/kursus) yang berkongsi database tetapi mempunyai susun atur dan brand distinction.

WAJIB:
1. Reka bentuk premium mobile-first BM/English, konsisten dengan contoh frontend, cantik dan pantas.
2. Bina search, filter, sort, favorites, copy prompt, multi-category browsing, produk details, saved progress dan error/empty/loading states yang betul-betul berfungsi. Jika gunakan Sign in with ChatGPT atau built-in storage, pastikan data peribadi berizin dan dilindungi.
3. Sediakan database persisten dan CMS pemilik dengan autentikasi/RBAC sebenar jika tersedia di Sites; jangan cipta fake admin. Staging, raw_sources, canonical products, prompts, links, rights, reviews, payment and delivery logs.
4. Import sumber dalam staging dahulu. Simpan original URL, provenance, row/page, source hash. Detect duplicates, review manually, and gate publication. Jangan ubah label/kuantiti prompt untuk menyembunyikan sumber asal. Jangan publish bahan pihak ketiga tanpa bukti lesen.
5. ToyyibPay: sediakan integrasi **sandbox terlebih dahulu**, secret on server, createBill, verify callback hash mengikut dokumentasi rasmi ToyyibPay, cross-check via getBillTransactions, verify amount/order/billCode, idempotent grant, restricted delivery. Jangan letak kunci API di client. Jangan aktifkan checkout sebenar hingga pemilik membekalkan secrets melalui sistem pengurusan rahsia, nama produk, harga sah, URL delivery dan mengesahkan ujian sandbox.
6. Notion ialah landing/preview opsyenal. Public Notion pages bukan paywall produk premium; pastikan subpages tidak bocor.
7. Dashboard admin: katalog dan search, import, moderation, editorial workflow, link checker, duplicate queue, license evidence, order status, campaign analytics berizin, delivery failure alerts.
8. SEO: canonical slug, sitemap, metadata, structured data hanya untuk data verified. WCAG 2.2 AA, focus states, keyboard, screen reader text. Uji mobile 320/390/768px, desktop dan performance real hosted.
9. Audit semua URL owner-supplied dan asingkan verified/unverified; jangan mereka-reka tautan sosial, harga, testimoni atau nombor produk. Label stok audit sebagai DRAFT/NOT VERIFIED.
10. Halaman polisi privasi, terms, refunds, digital delivery dan affiliate disclosure mesti wujud sebagai DRAF pemilik yang disemak sebelum publish.
11. Lakukan pemeriksaan automated unit, integration, browser visual dan E2E; berikan keputusan PASS/FAIL untuk setiap fungsi. Buat pembetulan dan retest jika gagal.
12. Akhir sekali, tunjukkan preview peranti mudah alih dan desktop, senarai yang BERFUNGSI, yang MEMERLUKAN konfigurasi, keputusan ujian, pautan/lesen belum disahkan dan langkah deploy. **JANGAN publish kepada umum sehingga saya beri kelulusan nyata.**

Mulakan dengan mengenal pasti modul, data sebenar yang tersedia dan risiko penting; kemudian hasilkan aplikasi sebenar. Jangan gantikan fungsi sebenar dengan placeholder yang berpura-pura aktif. Jika tidak boleh lakukan sesuatu dalam Sites, jelaskan limitasi dan cadangkan sambungan backend yang selamat tanpa berpura-pura lengkap.',NULL,'NOT TESTED','base','d0bd95754636ce0a1c86a5a5f313d446f3bb8ab18c81b26ee1b08a79d6c0feaa');
INSERT OR REPLACE INTO prompt_records (id,title,category,prompt_text,source_url,test_status,origin,sha256) VALUES ('USER-IA-001','Seni bina maklumat dan navigasi laman web','Reka Bentuk & Penjenamaan','Design the information architecture for a {website_type} serving {audience}.
Available content and offers: {content_inventory}. Primary conversion: {primary_conversion}. Maximum preferred primary-nav items: {navigation_limit}.
Create a sitemap and navigation hierarchy that helps first-time visitors discover the right page with minimal confusion. Group pages by user intent, propose descriptive navigation labels, define parent-child relationships, and identify the best path from the homepage to the primary conversion. Distinguish required pages from optional future pages.
Output a tree-style sitemap, a page inventory with page purpose and unique content angle, recommended header/footer navigation, an internal-linking plan, and mobile navigation behavior. Flag duplicate or overlapping pages. Do not add pages only to target more keywords; every page needs a distinct audience need.',NULL,'NOT TESTED','curated','57e3f7b30def74bf076fbce7a63fc4d420c06593c9ee70f7b6600dbd236c64c7');
